"""가격예측 패널."""
import base64, os, sys

BASE = os.path.dirname(os.path.abspath(__file__))
D = ''


def main():
    if not os.path.isdir(os.path.join(BASE, ".git")): print("ERROR"); return 1
    f = open(os.path.join(BASE, "docs", "index.html"), "wb")
    d = base64.b64decode(D); f.write(d); f.close()
    print("OK", len(d)); return 0


sys.exit(main())